-- migrate-spec-testlib-replace.sql — 规格书检验标准库(spec.test)按设计整库替换(2026-09-20)
--
-- 用户口径:检验项目及标准的标准库按《规格书细分.xlsx》sheet「检验项目及标准」重写,
--           原有标准库内容**全删**,改为该 sheet 的 **18 个检验项目**(序号 1..18),
--           每个项目内部的多行(合并单元格表达的子行)保留 ⇒ 共 47 条子项。
--
-- 真源说明(重要):前端「标准库」弹窗读的是 **数据库** `/stdlib/list?lib=spec.test`(all=1),
--   不是前端常量;前端 specTestLib.js 仅用于**兜底展示**与**组序**。
--   故本次必须同时改两处,否则界面看到的还是旧的 26 组:
--     · DB  —— 本脚本(删旧 48 条 + 插入新 47 条)
--     · 前端 —— tools/gen/gen-spec-testlib-from-design.cjs --write 重新生成 specTestLib.js
--
-- 与旧库的差异(全删后重建):
--   旧 26 组 48 子项(源《测试项目汇总.xlsx》)→ 新 18 组 47 子项(源《规格书细分.xlsx》该 sheet)
--   被删除的 8 个组(新设计里没有):黄水测试 / 浸泡口感测试 / COD性能测试 / 阻垢性能测试 /
--     抑菌性能测试 / 过流杀菌性能测试 / 碱性性能测试 / 矿化（富锶或微矿化）性能测试
--   同时旧库里的占位符写法(**±*g 之类)一并换成设计中的实测值(47.5-49.2g 等)。
--
-- 幂等:先按 lib_code 删除全部 spec.test 行,再从 JSON 重建 ⇒ 可重复执行、结果一致。
--   ⚠ 删除是**物理删除**:标准库弹窗里的"停用(enabled=0)"条目也会一并清掉,符合"全删重建"口径。
--
-- 用法:sqlcmd -S localhost -d HSDZ_MES -U yinjia -P '***' -b -f 65001 -i tools/migrate-spec-testlib-replace.sql
USE HSDZ_MES;
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
GO

DECLARE @before int = (SELECT COUNT(*) FROM yj_std_lib WHERE lib_code = N'spec.test');
PRINT N'--- 替换前 spec.test 条数 = ' + CAST(@before AS varchar) + N'(旧库 48 条)---';

DELETE FROM yj_std_lib WHERE lib_code = N'spec.test';
PRINT N'--- 已删除旧条目 ---';
GO

-- ═══════════════════════════════════════════════════════════════════
-- 插入新库:18 个检验项目 / 47 条子项(内容由 gen-spec-testlib-from-design.cjs 生成)
-- ═══════════════════════════════════════════════════════════════════
;

GO

-- ═══ 核对 ═══
PRINT N'--- 替换后:组数(去重 item_code)与条数 ---';
SELECT CAST(COUNT(DISTINCT item_code) AS varchar) + N' 个检验项目 / ' + CAST(COUNT(*) AS varchar) + N' 条子项' AS result
FROM yj_std_lib WHERE lib_code = N'spec.test';

PRINT N'--- 逐组条数(应为 18 行)---';
SELECT ROW_NUMBER() OVER (ORDER BY MIN(seq)) AS 序号, item_code AS 检验项目, COUNT(*) AS 子项数
FROM yj_std_lib WHERE lib_code = N'spec.test'
GROUP BY item_code ORDER BY MIN(seq);
