INSERT INTO yj_std_lib (lib_code, item_code, seq, content, enabled, asp_user1, asp_time1)
VALUES
  (N'spec.test', N'*外观', 10, N'{"v":2,"group":"*外观","name":"","req":"-清洁、无破损无压痕，无裂纹,无倾斜等缺陷\n-切面平整无锯齿纹路，无明显缺角\n-切面无残留炭渣","method":"目视","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*炭棒尺寸', 20, N'{"v":2,"group":"*炭棒尺寸","name":"","req":"外径：34.5±0.5mm","method":"游标卡尺","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*炭棒尺寸', 30, N'{"v":2,"group":"*炭棒尺寸","name":"","req":"内径：12.5±0.5mm","method":"游标卡尺","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*炭棒尺寸', 40, N'{"v":2,"group":"*炭棒尺寸","name":"","req":"长度：99±0.5mm","method":"游标卡尺","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'重量', 50, N'{"v":2,"group":"重量","name":"炭棒重量","req":"47.5-49.2g","method":"电子秤","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'重量', 60, N'{"v":2,"group":"重量","name":"（干重）","req":"47.5-49.2g","method":"电子秤","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'重量', 70, N'{"v":2,"group":"重量","name":"*出货重量","req":"＞47g","method":"电子秤","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'强度', 80, N'{"v":2,"group":"强度","name":"*抗压强度","req":"≥30kgf","method":"将炭棒水平放置在仪器上，调整间距40mm，设置下压速度5mm/min，按测试键，仪器自动下压，断裂后读取压断时最大力压力值","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'强度', 90, N'{"v":2,"group":"强度","name":"跌落强度","req":"成型强度：高度50cm，垂直跌落3次，炭棒无断裂","method":"将活性炭棒放置在50cm高处，3次自由跌落到水泥地板上，测试后，活性炭棒不可有破损现象","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'强度', 100, N'{"v":2,"group":"强度","name":"（裸棒）","req":"成品强度（一切二）：高度60cm，垂直跌落3次，炭棒无断裂","method":"将活性炭棒放置在50cm高处，3次自由跌落到水泥地板上，测试后，活性炭棒不可有破损现象","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'#*压降', 110, N'{"v":2,"group":"#*压降","name":"","req":"≤20kpa","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，测试用水纯水/超纯水，水温控制25±1℃，测试流速0.9L/min，滤前前后接装压力表，压力表距离滤芯接口位置长度50mm，通水10min后记录压差值（滤芯前压-后压）。","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*黑水及颗粒物测试', 120, N'{"v":2,"group":"*黑水及颗粒物测试","name":"初始黑水测试","req":"初始：第一杯500ml，轻微黑水/白水，浊度≤20NTU","method":"将炭棒组装好装入滤瓶（可旋盖大T），按进水方向通水测试用水纯水/超纯水，测试流速0.9±0.1L/min，\n1.用烧杯接第一杯500ml，观察出水及测试浊度值；","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*黑水及颗粒物测试', 130, N'{"v":2,"group":"*黑水及颗粒物测试","name":"浸泡黑水及颗粒物","req":"浸泡4H：无肉眼可见黑水，浊度≤3NTU，颗粒物≤4颗","method":"2.冲水5min后，浸泡4H，陶瓷杯接出水200ml，观察出水情况及测试浊度值；正常照明下，用肉眼观察杯底部颗粒物，颗粒物≤4颗","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*黑水及颗粒物测试', 140, N'{"v":2,"group":"*黑水及颗粒物测试","name":"（裸棒）","req":"浸泡4H：无肉眼可见黑水，浊度≤3NTU，颗粒物≤4颗","method":"","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*一级颗粒物去除率', 150, N'{"v":2,"group":"*一级颗粒物去除率","name":"","req":"0.5-1μm颗粒物去除率≥95%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分直接连接，水流方向外进内出，用纯水冲洗30min，流速2.0L/min，炭棒出水颗粒＜500颗/ml，用A2粉配置加标水0.5-1μm颗粒数10000±1000颗/ml，将冲洗干净的炭棒通过加标水，流速0.9±0.1L/min，通标2分钟取样测试，计算颗粒物去除率","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'隔夜浸泡口感/气味', 160, N'{"v":2,"group":"隔夜浸泡口感/气味","name":"","req":"浸泡15-24H：出水无异味、口感正常，浊度值≤3NTU","method":"1）将炭棒组装好装入滤瓶（可旋盖大T），测试流速0.9±0.1L/min，测试用水纯水/超纯水，冲水3min后浸泡15-24H，接水量250ml，品尝出水及闻气味，测试浊度值\n品尝人数：至少4人","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'VOC性能测试', 170, N'{"v":2,"group":"VOC性能测试","name":"初始VOC去除率","req":"≥95%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分直接连接，水流方向外进内出，测试流速0.9±0.1L/min，参考NSF 53标准方法配置加标水，原水平均浓度控制在300μg/L±10%，通入加标水5min后取样测试，计算去除率。","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'VOC性能测试', 180, N'{"v":2,"group":"VOC性能测试","name":"除VOC寿命","req":"寿命600L，全程加标","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分直接连接，水流方向外进内出，测试流速0.9±0.1L/min，参考NSF 53标准方法配置加标水，原水平均浓度控制在300μg/L±10%，在额定净水0%、25%、50%、75%、100%进行取样测试，计算去除率。","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'VOC性能测试', 190, N'{"v":2,"group":"VOC性能测试","name":"除VOC寿命","req":"去除率≥95%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分直接连接，水流方向外进内出，测试流速0.9±0.1L/min，参考NSF 53标准方法配置加标水，原水平均浓度控制在300μg/L±10%，在额定净水0%、25%、50%、75%、100%进行取样测试，计算去除率。","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
  (N'spec.test', N'*除铅性能测试（PH8.5&6.5)', 200, N'{"v":2,"group":"*除铅性能测试（PH8.5&6.5)","name":"初始铅去除率","req":"≥96.7%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分直接连接，水流方向外进内出，测试流速0.9±0.1L/min，参考NSF 53标准方法配置加标水，原水平均浓度控制在150μg/L±10%，通入加标水5min后取样测试，计算去除率。","basis":"银嘉测试标准"}', 1, N'rebuild-2026-09-20', SYSDATETIME()),
